import hashlib,json,pathlib,struct,subprocess,sys
r=json.loads(pathlib.Path(sys.argv[1]).read_bytes())
def h(b):return hashlib.sha256(b).hexdigest()
checks=0
for p in r["source_pins"]:
 b=subprocess.check_output(["git","show",p["commit"]+":"+p["path"]]);assert len(b)==p["git_bytes"] and h(b)==p["git_sha256"];checks+=1
for p in r["source_regions"]:
 b=subprocess.check_output(["git","show",p["git_commit"]+":"+p["path"]]);q=b"".join(b.splitlines(keepends=True)[p["first_line"]-1:p["last_line"]]);assert len(q)==p["region_bytes"] and h(q)==p["region_sha256"];checks+=1
pe=pathlib.Path(r["native_evidence"]["pe"]["path"]).read_bytes();assert h(pe)==r["native_evidence"]["pe"]["sha256"];checks+=1
for p in r["native_evidence"]["native"]+r["native_evidence"]["eh"]+[r["node_profile"]]:
 b=bytes.fromhex(p["hex"]);assert len(b)==p["bytes"] and h(b)==p["sha256"] and pe[p["pe_file_offset"]:p["pe_file_offset"]+len(b)]==b;checks+=1
 if "instructions" in p:assert b==b"".join(bytes.fromhex(i["bytes_hex"]) for i in p["instructions"]) and len(p["instructions"])==p["instruction_rows"]
for p in r["native_evidence"]["native"]:
 for e in p["exports"]:
  b=pathlib.Path(e["frozen_path"]).read_bytes();assert len(b)==e["bytes"] and h(b)==e["sha256"];checks+=1
assert r["implementation_ready"] is False and r["native_origin_permission"] is False
print(json.dumps({"checks":checks,"source_pins":len(r["source_pins"]),"regions":len(r["source_regions"]),"native_instructions":178,"pass":True}))
